    public Settings silence_audition_windows(Settings boundary,double speed)
    {
        var windows=new Godot.Collections.Array<Settings>();foreach(string side in new[]{"left","right"}){var interval=boundary.TryGetValue(side,out var found)?found:Variant.From(Vector2.Zero);double first,end;if(interval.VariantType==Variant.Type.Vector2){first=interval.AsVector2().X;end=interval.AsVector2().Y;}else if(interval.VariantType==Variant.Type.Dictionary){var entry=interval.AsGodotDictionary();if(!entry.TryGetValue("start",out var a)||!entry.TryGetValue("end",out var b)||a.VariantType is not Variant.Type.Float and not Variant.Type.Int||b.VariantType is not Variant.Type.Float and not Variant.Type.Int)return Failure("Invalid audition window.");first=a.AsDouble();end=b.AsDouble();}else return Failure("Invalid audition window.");if(!double.IsFinite(first)||!double.IsFinite(end)||first<0||end<first||end-first>.35*speed+.000001)return Failure("Invalid audition window.");double fade=(boundary.TryGetValue(side=="left"?"fade_out":"fade_in",out var value)?value.AsDouble():0)*speed;if(!double.IsFinite(fade)||fade<0||fade>1)return Failure("Invalid audition fade.");windows.Add(new Settings {["start"]=first,["end"]=end,["fade"]=fade,["left"]=side=="left"});}return new Settings {["error"]="",["windows"]=windows};
    }
    public Settings silence_boundary_audio(Variant value,Settings boundary,RefCounted? job)
    {
        if(Cancelled(job))return Failure("Cancelled.");double speed=boundary.TryGetValue("speed",out var speedValue)?speedValue.AsDouble():0;if(!double.IsFinite(speed)||speed<=0||speed>16)return Failure("Unsupported audition speed.");var prepared=silence_audition_windows(boundary,speed);if(prepared["error"].AsString().Length>0)return prepared;string curve=boundary.TryGetValue("fade_curve",out var fadeCurve)?fadeCurve.AsString():"linear";var windows=prepared["windows"].AsGodotArray();if(value.VariantType==Variant.Type.String&&value.AsString().GetExtension().ToLowerInvariant()=="wav"){using var pcm=new AudioPcmFileOperations();var info=pcm.inspect(value.AsString());if(!info.TryGetValue("error",out var error)||error.AsString().Length>0)return Failure("Boundary audition requires supported mono/stereo PCM WAV. "+(info.TryGetValue("error",out var detail)?detail.AsString():"Invalid WAV metadata."));return pcm_silence_boundary(value.AsString(),info,windows,speed,curve,job);}string problem=silence_source_error(value);if(problem.Length>0)return Failure(problem);var signature=value.VariantType==Variant.Type.String?analysis_file_signature(value.AsString()):new Settings();if(value.VariantType==Variant.Type.String&&signature.Count==0)return Failure("The source is unavailable for audition.");var stream=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("source",value,Variant.From(job)).As<AudioStream>();if(Cancelled(job))return Failure("Cancelled.");if(stream==null)return Failure("The source is unavailable for audition.");problem=silence_source_error(stream);if(problem.Length>0)return Failure(problem);var output=new List<Vector2>();const int rate=12000;foreach(var raw in windows){var window=raw.AsGodotDictionary();double first=window["start"].AsDouble(),end=window["end"].AsDouble();if(end<=first)continue;if(end>stream.GetLength()+.0001)return Failure("The source ended before the audition boundary.");if(Cancelled(job))return Failure("Cancelled.");var decoded=Decode(stream,rate,first,end-first,6);if(decoded["error"].AsString().Length>0)return decoded;var samples=decoded["samples"].AsVector2Array();if(samples.Length!=(int)Math.Round((end-first)*rate,MidpointRounding.AwayFromZero))return Failure("The source ended before the audition boundary.");double fade=window["fade"].AsDouble()*rate;bool left=window["left"].AsBool();for(int index=0;index<samples.Length;index++){if(index%16384==0&&Cancelled(job))return Failure("Cancelled.");double distance=left?samples.Length-1-index:index;if(fade>0&&distance<fade){double gain=Math.Clamp(distance/fade,0,1);samples[index]*=(float)(curve=="equal_power"?Math.Sin(gain*Math.PI*.5):gain);}}output.AddRange(samples);}if(output.Count==0)return Failure("No retained audio borders this removal.");if(Cancelled(job))return Failure("Cancelled.");if(value.VariantType==Variant.Type.String&&!signature.RecursiveEqual(analysis_file_signature(value.AsString())))return Failure("The source changed during audition preparation. Analyze it again.");using var cache=new AudioSourceCacheOperations();return new Settings {["error"]="",["stream"]=cache.to_wav(output.ToArray(),rate,true),["speed"]=speed,["seconds"]=(double)output.Count/rate/speed};
    }
    public Settings pcm_silence_boundary(string path,Settings info,GArray windows,double speed,string curve,RefCounted? job)
    {
        int rate=info["rate"].AsInt32();double sourceDuration=info["duration"].AsDouble();if(!double.IsFinite(sourceDuration)||sourceDuration<=0||sourceDuration>86400)return Failure("PCM dialogue sources must be nonempty and at most 24 hours long.");long total=0;foreach(var raw in windows){var window=raw.AsGodotDictionary();if(window["end"].AsDouble()>sourceDuration+.000001)return Failure("The source ended before the audition boundary.");long first=(long)Math.Round(window["start"].AsDouble()*rate,MidpointRounding.AwayFromZero),frames=(long)Math.Round(window["end"].AsDouble()*rate,MidpointRounding.AwayFromZero)-first;window["first_frame"]=first;window["frames"]=frames;if(first<0||frames<0||first+frames>info["frames"].AsInt64())return Failure("Invalid PCM audition frame window.");total+=frames;}if(total<=0)return Failure("No retained audio borders this removal.");if(total>2150402||total*8>AudioSourceCacheOperations.MaxDecodeBytes)return Failure("The PCM audition exceeds its short-window memory bound.");using var file=Godot.FileAccess.Open(path,Godot.FileAccess.ModeFlags.Read);if(file==null)return Failure("Could not open the PCM source for audition.");if(!pcm_file_current(path,info,file,true))return Failure("The PCM source changed before audition preparation. Analyze it again.");var output=new byte[checked((int)total*4)];int written=0;ulong checkedAt=Time.GetTicksMsec();using var pcm=new AudioPcmFileOperations();foreach(var raw in windows){var window=raw.AsGodotDictionary();int cursor=0,frames=window["frames"].AsInt32();double fade=window["fade"].AsDouble()*rate;while(cursor<frames){if(Cancelled(job))return Failure("Cancelled.");if(Time.GetTicksMsec()-checkedAt>=1000){checkedAt=Time.GetTicksMsec();if(!pcm_file_current(path,info,file,false))return Failure("The PCM source changed during audition preparation. Analyze it again.");}int count=Math.Min(AudioPcmFileOperations.MaxReadFrames,frames-cursor);var samples=pcm.read_frames(file,info,window["first_frame"].AsInt64()+cursor,count);if(samples.Length!=count)return Failure("The PCM source ended before the audition boundary.");for(int index=0;index<samples.Length;index++){double distance=window["left"].AsBool()?frames-1-cursor-index:cursor+index;double gain=fade>0?Math.Clamp(distance/fade,0,1):1;if(curve=="equal_power")gain=Math.Sin(gain*Math.PI*.5);var sample=samples[index]*(float)gain;short Pcm(float amplitude)=>(short)Math.Clamp(Math.Round(Math.Clamp((double)amplitude,-1,1)*32768,MidpointRounding.AwayFromZero),-32768,32767);BinaryPrimitives.WriteInt16LittleEndian(output.AsSpan((written+index)*4,2),Pcm(sample.X));BinaryPrimitives.WriteInt16LittleEndian(output.AsSpan((written+index)*4+2,2),Pcm(sample.Y));}cursor+=count;written+=count;Progress(job,(double)written/total,"Preparing bounded PCM boundary audition");}}if(!pcm_file_current(path,info,file,true))return Failure("The PCM source changed during audition preparation. Analyze it again.");if(Cancelled(job))return Failure("Cancelled.");var stream=new AudioStreamWav {Format=AudioStreamWav.FormatEnum.Format16Bits,MixRate=rate,Stereo=true,Data=output};if(Cancelled(job)){stream.Dispose();return Failure("Cancelled.");}if(!pcm_file_current(path,info,null,true)){stream.Dispose();return Failure("The PCM source changed during audition preparation. Analyze it again.");}return new Settings {["error"]="",["stream"]=stream,["speed"]=speed,["seconds"]=(double)total/rate/speed,["source_signature"]=info.Duplicate()};
    }
